6.3 5.3 灾难性自付：超过家庭 10% 收入的 OOP

Codeif (!is.null(external_data) && !is.null(external_data$gho)) {
  cata &lt;- catastrophic_oop_share(
    build_master_panel(master_enriched, external_data),
    threshold = 10
  )
  if (nrow(cata)) {
    cata_join &lt;- cata |&gt;
      dplyr::left_join(
        master_enriched |&gt; dplyr::distinct(.data$iso3_code, .data$income_group),
        by = "iso3_code"
      ) |&gt;
      dplyr::filter(!is.na(.data$income_group)) |&gt;
      dplyr::group_by(.data$year, .data$income_group) |&gt;
      dplyr::summarise(
        median_pct = stats::median(.data$catastrophic_pct, na.rm = TRUE),
        .groups = "drop"
      )
    ggplot2::ggplot(cata_join,
                     ggplot2::aes(.data$year, .data$median_pct,
                                   colour = .data$income_group)) +
      ggplot2::geom_line(linewidth = 1.3) +
      scale_colour_brand_income() +
      labs_news(
        title    = "\u707e\u96be\u6027\u81ea\u4ed8\u4e0b\u964d\u4f46\u4e0d\u5747",
        subtitle = "\u4e2d\u4f4e\u6536\u5165\u56fd\u5bb6\u4ecd\u7136\u8d85\u8fc7 12% \u5bb6\u5ead\u88ab\u538b\u5305",
        x = NULL, y = "\u4eba\u53e3 % (\u6536\u5165\u7ec4\u4e2d\u4f4d\u6570)"
      )
  }
}

7.1 6.1 卫生占财政（GHE/GGE）的 23 年走势
Codemaster_panel &lt;- build_master_panel(master_enriched, external_data)

if ("gov_exp_gdp" %in% names(master_panel)) {
  d &lt;- master_panel |&gt;
    dplyr::filter(is.finite(.data$gghed_che),
                  is.finite(.data$gov_exp_gdp),
                  .data$gov_exp_gdp &gt; 0) |&gt;
    dplyr::mutate(ghe_gge = .data$gghed_che / .data$gov_exp_gdp * 100) |&gt;
    dplyr::group_by(.data$year, .data$continent) |&gt;
    dplyr::summarise(median_pct = stats::median(.data$ghe_gge,
                                                  na.rm = TRUE),
                     .groups = "drop") |&gt;
    dplyr::filter(!is.na(.data$continent))

  ggplot2::ggplot(d, ggplot2::aes(.data$year, .data$median_pct,
                                    colour = .data$continent)) +
    ggplot2::geom_line(linewidth = 1.4) +
    scale_colour_brand_continent() +
    labs_news(
      title    = "\u536b\u751f\u5360\u653f\u5e9c\u603b\u652f\u51fa\u6bd4 \u00b7 \u5404\u5927\u6d32\u4e2d\u4f4d\u6570",
      subtitle = "\u4e1a\u9886\u533b\u4fdd\u4f53\u7cfb\u7684\u6b27\u6d32\u8fbe\u5230 \u224815%\uff0c\u9ad8\u4e8e\u5176\u4ed6\u5927\u6d32 5pp",
      x = NULL, y = "GHE/GGE (%)",
      caption = "\u6570\u636e\u6e90 \u00b7 GHED + IMF GFS  \u00b7  \u5206\u6790 Analysis: \u5e84\u9882"
    )
}

